; Regression ROM for side track O (O.2, input movies; PLAN.md "Side track
; O"): the determinism gate's game. Once a frame (at LY 146, after the
; frame start where a movie's input word is latched) it reads both pad
; groups into J, makes 64 reads spread over banks 0 to 7 of an MBC5
; cartridge (128 KiB of generated bytes: most reads miss the core's DDR
; cache, so the harness's random AXI latency stalls the core differently
; on each run), mixing each byte and J into a 16-bit digest, then sends J
; and the digest over the serial port (three bytes a frame; the harness
; collects them on the byte channel). An input a frame early or late
; changes every byte after it; a core whose result depended on DDR timing
; would too.
;
; Assembled by `make gb-asm` into build/gb/asm/joybank.gb.

DEF rP1 EQU $FF00
DEF rSB EQU $FF01
DEF rSC EQU $FF02
DEF rLY EQU $FF44
DEF rROMB0 EQU $2000
DEF hCount EQU $FF80            ; frames so far, mixed in: no fixed point

SECTION "Header", ROM0[$100]
    nop
    jp Start
    ds $147 - @, 0
    db $19                      ; MBC5
    db $02                      ; 128 KiB ROM: 8 banks
    db $00                      ; no RAM
    ds $150 - @, 0

SECTION "Main", ROM0[$150]
Start:
    di
    ld sp, $FFFE
    ld de, $ACE1                ; the digest
    xor a
    ldh [hCount], a
Frame:
.off:                           ; leave line 146 (a frame's work is shorter)
    ldh a, [rLY]
    cp 146
    jr z, .off
.on:
    ldh a, [rLY]
    cp 146
    jr nz, .on
    ld a, $20                   ; the directions: the high nibble of J
    ldh [rP1], a
    ldh a, [rP1]
    ldh a, [rP1]
    and $0F
    swap a
    ld b, a
    ld a, $10                   ; the buttons: the low nibble
    ldh [rP1], a
    ldh a, [rP1]
    ldh a, [rP1]
    and $0F
    or b
    ld b, a
    ld a, $30
    ldh [rP1], a
    ldh a, [hCount]
    inc a
    ldh [hCount], a
    add d
    ld d, a
    ld c, 64
.read:
    ld a, e                     ; bank: the digest's low 3 bits
    and 7
    ld [rROMB0], a
    ld a, d                     ; address: $4000 + (DE & $3FFF)
    and $3F
    or $40
    ld h, a
    ld l, e
    ld a, [hl]
    xor b
    add e
    ld e, a
    ld a, d
    rrca
    xor e
    ld d, a
    dec c
    jr nz, .read
    ld a, b
    call Send
    ld a, e
    call Send
    ld a, d
    call Send
    jr Frame

; A over the serial port (internal clock), waiting for the transfer's end
Send:
    ldh [rSB], a
    ld a, $81
    ldh [rSC], a
.wait:
    ldh a, [rSC]
    bit 7, a
    jr nz, .wait
    ret

; banks 1 to 7: bytes from a linear congruential generator (bank 0 holds
; the code and zeros above it)
DEF SEED = 12345
FOR BNK, 1, 8
SECTION "Data{d:BNK}", ROMX[$4000], BANK[BNK]
    REPT $4000
        REDEF SEED = (SEED * 1103515245 + 12345) & $7FFFFFFF
        db (SEED >> 16) & $FF
    ENDR
ENDR
